# Own-wording subclasses of Grim Hollow Player's Guide, 2014 rules, batch B: Fighter, Monk, Paladin, Ranger.
COMPOUNDS = [
 ["Adrenal Injection", "For 1 minute your speed rises by 10 ft and your jump distances triple."],
 ["Allsense Injection", "For 1 minute you have blindsight out to 30 ft."],
 ["Arcane Eye Oil", "For 1 hour you sense magic as with detect magic."],
 ["Draught of Bear's Endurance", "For 10 minutes you have Advantage on Constitution checks and saves."],
 ["Draught of Bull's Strength", "For 10 minutes you have Advantage on Strength checks and saves."],
 ["Draught of Cat's Grace", "For 10 minutes you have Advantage on Dexterity checks and saves."],
 ["Draught of Eagle's Splendor", "For 10 minutes you have Advantage on Charisma checks and saves."],
 ["Draught of Fox's Cunning", "For 10 minutes you have Advantage on Intelligence checks and saves."],
 ["Draught of Owl's Wisdom", "For 10 minutes you have Advantage on Wisdom checks and saves."],
 ["Elfsight Oil", "For 8 hours you have darkvision out to 120 ft."],
 ["Fleshknit Phosphate", "For 1 minute, if you have at least 1 hit point, you heal hit points equal to your Proficiency Bonus at the start of each of your turns."],
 ["Ironmind Injection", "For 1 hour you have Advantage on saves against being Charmed or Frightened."],
 ["Liquid Courage", "You gain temporary hit points equal to your Constitution score plus twice your fighter level. Any left vanish after 1 minute."],
 ["Liquid Rage", "For 1 minute your weapon attacks deal an extra 1d4 damage."],
 ["Presto Powder", "For 10 minutes you have Advantage on initiative checks and can take Dash or Disengage as a bonus action on each of your turns."],
 ["Spellshine Ointment", "For 1 minute you have Resistance to spell damage."],
 ["Steelskin Ointment", "For 1 minute you have Resistance to Bludgeoning, Piercing and Slashing damage."],
 ["Tenmen Tincture", "For 1 hour you count as one size larger for carrying capacity and ignore the Heavy property of weapons."],
]
def _comp(l, n, key, title):
    return {"l": l, "k": "opts", "n": n, "key": key, "feature": "Compound Creator", "title": title, "list": COMPOUNDS}

